bool ApiLogger::checkTimeInterval()
{
   const bool hasIntervalEnded = std::chrono::steady_clock::now() > m_monotonicEndTimepoint;

   if (hasIntervalEnded)
   {
      // Next interval's start times are this interval's end times
      m_startTimepoint += m_intervalDuration;
      m_monotonicStartTimepoint = m_monotonicEndTimepoint;

      // Calculate next interval's end times
      m_monotonicEndTimepoint += m_intervalDuration;
   }

   return hasIntervalEnded;
}

