// Manipulate measurements for debugging purposes: remove or scale variances according to signal,
// constellation, and measurements type.
void applyCalStochasticModel(GnssMeasurements& meas)
{
   // pseudorange measurements: filter and scale variances
   auto& codeMeasMap = meas.data.pseudorangeMeasurements;
   for (auto itMeas = codeMeasMap.begin(); itMeas != codeMeasMap.end(); ++itMeas)
   {
      double& covariance = itMeas->second.pseudorange.covariance;
      covariance = getCalVariance<PseudorangeMeasurement>(itMeas->first.constellation, covariance);
   }
   // phaserange measurements: filter and scale variances
   auto& phaseMeasMap = meas.data.phaserangeMeasurements;
   for (auto itMeas = phaseMeasMap.begin(); itMeas != phaseMeasMap.end(); ++itMeas)
   {
      double& covariance = itMeas->second.phaseRange.covariance;
      covariance = getCalVariance<PhaserangeMeasurement>(itMeas->first.constellation, covariance);
   }
}

// Process the ResetAction
   void process(const ResetAction resetAction)
   {
      // Test logic: Provoke Timeout
      if (
         ((resetAction == ResetAction::Prepare) && m_timeoutOnPrepare)
         || ((resetAction == ResetAction::Execute) && m_timeoutOnExecute))
      {
         std::this_thread::sleep_for(DELAY_BEYOND_TIMEOUT);
      }
      else if ((resetAction == ResetAction::Prepare) && m_delayWithinTimeout)
      {
         // Once only, so clear flag
         m_delayWithinTimeout = false;
         std::this_thread::sleep_for(DELAY_WITHIN_TIMEOUT);
      }

      // Standard reset logic
      if (resetAction == ResetAction::Execute)
      {
         reset();
      }

      m_resetCompleteCallback();
   }

/// @brief Finds a GNSS key in the set.
   /// @param key The GNSS key to look up.
   /// @return Iterator to the found element, or end() if not found.
   Iterator find(const GnssKey& key = GnssKey())
   {
      auto itr = m_indexMap.find(T_STATETYPE::sanitizedStateKeySetKey(key));
      if (itr == m_indexMap.end())
      {
         return m_keySet.end();
      }
      using Diff = typename std::iterator_traits<decltype(m_keySet.begin())>::difference_type;
      return m_keySet.begin() + static_cast<Diff>(itr->second);
   }

