private:
   Iterator eraseSanitizedKey(const GnssKey& key)
   {
      auto itr = m_indexMap.find(key);
      if (itr == m_indexMap.end())
      {
         return m_keySet.end();
      }

      auto selectedIdx = itr->second;
      auto lastIdx = m_keySet.size() - 1;

      if (selectedIdx != lastIdx)
      {
         // Swap with last element
         std::swap(m_keySet[selectedIdx], m_keySet[lastIdx]);
         // Update index map of last element for swapped element
         m_indexMap[m_keySet[selectedIdx]] = selectedIdx;
      }

      // Remove the key from map and vector
      m_indexMap.erase(itr);
      m_keySet.pop_back();

      // Return iterator to the element that was swapped in, or end if erased last
      if (selectedIdx < m_keySet.size())
      {
         return m_keySet.begin() + static_cast<Index>(selectedIdx);
      }

      return m_keySet.end();
   }

