EntropyCollector::EntropyCollector()
{
   auto cpuTime = static_cast<std::uint64_t>(0U);
   const auto nanoseconds = std::chrono::high_resolution_clock::now().time_since_epoch().count();

   for (std::uint32_t i = 0U; i < ENTROPY_SAMPLING_ITERATIONS; i++)
   {
      const auto start = std::chrono::high_resolution_clock::now();

      // Yield the thread to introduce timing variability for entropy collection.
      // This technique is used by entropy gathering methods used in Linux's /dev/random,
      // where unpredictable timing differences between context switches are leveraged.
      std::this_thread::yield();
      const auto end = std::chrono::high_resolution_clock::now();
      cpuTime += static_cast<uint64_t>((end - start).count());
   }

   m_state = mix(static_cast<uint64_t>(nanoseconds) ^ cpuTime);
}

