mxml_node_t*
HlfXmlSerializer::serializeHeader(mxml_node_t* const parent, const HlfHeaderRecord& header)
{
   // Dispatch to the matching serialize() overload by recovering the concrete
   // subtype via dynamic_cast. Sub-type tag steers the cast to the correct
   // target; a null result means the record was constructed with a sub-type
   // that does not match its concrete class, which is treated as a hard error.
   switch (header.getSubType())
   {
      case HlfRecordSubType::HeaderStartTime:
      {
         const auto* const derived = dynamic_cast<const HlfStartTimeHeaderRecord*>(&header);

         if (derived == nullptr)
         {
            throw XmlSerializationException("Failed to serialize HLF start time header");
         }

         HlfHeaderRecordXmlSerializer::serialize(parent, *derived);
         break;
      }

      case HlfRecordSubType::HeaderInputDescription:
      {
         const auto* const derived = dynamic_cast<const HlfInputDescriptionHeaderRecord*>(&header);

         if (derived == nullptr)
         {
            throw XmlSerializationException("Failed to serialize HLF input description header");
         }

         HlfHeaderRecordXmlSerializer::serialize(parent, *derived);
         break;
      }

      case HlfRecordSubType::HeaderRecordingInformation:
      {
         const auto* const derived
            = dynamic_cast<const HlfRecordingInformationHeaderRecord*>(&header);

         if (derived == nullptr)
         {
            throw XmlSerializationException("Failed to serialize HLF recording information header");
         }

         HlfHeaderRecordXmlSerializer::serialize(parent, *derived);
         break;
      }

      case HlfRecordSubType::HeaderEndTime:
      {
         const auto* const derived = dynamic_cast<const HlfEndTimeHeaderRecord*>(&header);

         if (derived == nullptr)
         {
            throw XmlSerializationException("Failed to serialize HLF end time header");
         }

         HlfHeaderRecordXmlSerializer::serialize(parent, *derived);
         break;
      }

      case HlfRecordSubType::HeaderRecordingDescription:
      {
         const auto* const derived
            = dynamic_cast<const HlfRecordingDescriptionHeaderRecord*>(&header);

         if (derived == nullptr)
         {
            throw XmlSerializationException("Failed to serialize HLF recording description header");
         }

         HlfHeaderRecordXmlSerializer::serialize(parent, *derived);
         break;
      }

      case HlfRecordSubType::HeaderApplicationConfiguration:
      {
         const auto* const derived
            = dynamic_cast<const HlfApplicationConfigurationHeaderRecord*>(&header);

         if (derived == nullptr)
         {
            throw XmlSerializationException(
               "Failed to serialize HLF application configuration header");
         }

         HlfHeaderRecordXmlSerializer::serialize(parent, *derived);
         break;
      }

      case HlfRecordSubType::HeaderStaticData:
      default:
         throw XmlSerializationException("Unsupported header type");
   }

   return parent;
}

std::size_t HlfSplitter::writeHeaderRecords(std::ofstream& file, const HeaderInfo& headerInfo)
