//!  Description: Method performing an in-place conversion from a covariance matrix to a correlation matrix.
//!               Setting the argument uLowerUpper to Lower or Upper results in the conversion to be applied 
//!               only to the lower or upper triangular part of the matrix, respectively. The default value 
//!               (Lower&Upper) evaluates the correlation coefficients from the upper triangular part of the
//!               covariance matrix and stores the results both in the lower and upper triangular parts.
//!
ComputationInfo convertCovToCorrMatrix( unsigned int uLowerUpper = (Lower&Upper) )
{
    EIGEN_STATIC_ASSERT((Lower&Upper) != Lower && Lower != Upper && (Lower&Upper) != Upper, EIGEN_INTERNAL_COMPILATION_ERROR_OR_YOU_MADE_A_PROGRAMMING_MISTAKE);

    if( !(this->isSquare()) )
    {
        return InvalidInput;
    }

    const Index cDim = (*this).derived().rows();

    if( uLowerUpper == Upper || uLowerUpper == (Lower&Upper) )
    {
        for (Index idxCol = 0; idxCol < cDim; ++idxCol)
        {   
            for (Index idxRow = 0; idxRow < idxCol; ++idxRow)
            {   
                (*this)(idxRow, idxCol) /= std::sqrt( (*this)(idxRow, idxRow) * (*this)(idxCol, idxCol) );
            }
        }

        if( uLowerUpper == (Lower&Upper) )
        {
            (*this).template triangularView<Lower>() = (*this).template triangularView<Upper>().transpose();
        }
    }
    else if( uLowerUpper == Lower )
    {
        for (Index idxCol = 0; idxCol < cDim; ++idxCol)
        {   
            for (Index idxRow = idxCol + 1; idxRow < cDim; ++idxRow)
            {   
                (*this)(idxRow, idxCol) /= std::sqrt( (*this)(idxRow, idxRow) * (*this)(idxCol, idxCol) );
            }
        }
    }
    else
    {
        return InvalidInput;
    }

    (*this).derived().diagonal().setOnes();
    return Success;
}

