std::optional<ReconstructionTraits<PositionReconstruction>::AbsoluteData>
PositionReconstruction::reconstructFromAbsolute(const Time& requestTime)
{
   // Validate inputs and states
   if (m_positionIncrements.empty() || m_absolutePositions.empty())
   {
      return std::nullopt;
   }

   // 1. Find closest absolute position
   auto posWithMeta = findClosestAbsolutePosition(requestTime);
   if (!posWithMeta.metaData)
   {
      return std::nullopt;
   }

   // 2. Find increment containing request time
   const auto containingIt = findIncrementAtTime(posWithMeta.value.time, m_positionIncrements);
   if (containingIt == m_positionIncrements.cend())
   {
      return std::nullopt;
   }

   // 3. Initialize result
   EigenPosition result;
   result.time = posWithMeta.value.time;
   result.data = posWithMeta.value.data;

   // 4. Calculate and apply interpolated portion
   const auto alpha = calculateInterpolationFactor((*containingIt).value, posWithMeta.value.time);
   if (!alpha.has_value())
   {
      return std::nullopt;
   }
   applyInterpolatedIncrement(*alpha, (*containingIt).value, result);

   // 5. Apply subsequent increments
   const bool isNoGaps
      = accumulateSubsequentIncrements(std::next(containingIt), m_positionIncrements, result);
   if (!isNoGaps)
   {
      return std::nullopt;
   }

   return ReconstructionTraits<PositionReconstruction>::AbsoluteData(result, posWithMeta.metaData);
}

