void HlfSplitter::processHeaderRecord(
   BufferReader& reader,
   const std::vector<uint8_t>& headerRecord,
   const std::size_t size,
   HeaderInfo& headerInfo)
{
   // Extract subtype from header record
   reader.setIndex(GENERIC_HEADER_SIZE);
   HlfRecordSubType subType{};
   reader.read(&subType, SUB_TYPE_FIELD_SIZE);

   switch (subType)
   {
      case HlfRecordSubType::HeaderStartTime:
         // Get the recording start time and uptime from the start time header
         std::tie(headerInfo.startRecordingTime, headerInfo.startUptime)
            = parseStartTimeHeader(reader);
         headerInfo.recordingTime = headerInfo.startRecordingTime;
         headerInfo.currentUptime = headerInfo.startUptime;

         headerInfo.startTimeHeaderPos = headerInfo.headers.size();
         break;

      case HlfRecordSubType::HeaderEndTime:
         headerInfo.endTimeHeaderPos = headerInfo.headers.size();
         break;

      case HlfRecordSubType::HeaderInputDescription:
      case HlfRecordSubType::HeaderRecordingInformation:
      case HlfRecordSubType::HeaderRecordingDescription:
      case HlfRecordSubType::HeaderApplicationConfiguration:
      case HlfRecordSubType::HeaderStaticData:
      default:
         break;
   }

   // Add the header's bytes to the collection containing all the headers
   std::copy_n(headerRecord.begin(), size, std::back_inserter(headerInfo.headers));
}

void HlfRecordXmlParser::readXmlUntilChar(
   std::istream& xmlStream,
   std::vector<char>& elementChars,
   const char delimiterChar)
{
   const size_t buffSize = 128;
   std::array<char, buffSize> buff{};

   // Read data until delimiter is found
   bool keepReading = true;
   while (keepReading)
   {
      // The fail state needs to be cleared before the next operation on the stream
      if (xmlStream.rdstate() == std::ios::failbit)
      {
         xmlStream.clear();
      }

      // If the delimiter character was not found the failbit is set.
      auto charactersExtracted = xmlStream.getline(buff.data(), buffSize, delimiterChar).gcount();

      const uint32_t nullCharacterSize = 1;
      const bool isDelimiterFound = charactersExtracted != buffSize - nullCharacterSize;

      // When the delimiter is found the count will include the delimiter, however it is
      // not included in the output so adjust for it.
      if (isDelimiterFound)
      {
         charactersExtracted -= 1;
      }

      static_cast<void>(std::copy(
         buff.data(),
         buff.data() + charactersExtracted,
         std::back_inserter(elementChars)));

      keepReading = (xmlStream.rdstate() == std::ios::failbit);
   }

   elementChars.push_back(delimiterChar);
}

