/// @brief Removes stale keys from a fixed-capacity array of ambiguity states with key
/// sets, dropping ambiguity states that fall below a specified number of ambiguities after
/// filtering.
///
/// @param staleKeys Stale keys in the current epoch.
/// @param minAmbiguities  Minimum number of ambiguities a candidate must retain to be kept.
/// @param buffer Array with Fixed capacity of 2U; only the first bufferCount slots are valid.
/// @param bufferCount Count of valid entries in buffer; updated by this function.
inline void eraseStaleKeysFromBuffer(
   const StateKeySet<Ambiguity>& staleKeys,
   const std::size_t minAmbiguities,
   std::array<AmbiguityStateWithKeySet, 2U>& buffer,
   std::size_t& bufferCount)
{
   const auto originalCount = bufferCount;
   std::size_t writeIdx = 0U;

   for (std::size_t readIdx = 0U; readIdx < originalCount; ++readIdx)
   {
      const auto& candidate = buffer.at(readIdx);
      if (auto filteredKeys = getExclusiveKeys(candidate.keySet(), staleKeys);
          filteredKeys.size() >= minAmbiguities)
      {
         // Compute the indices of the filteredKeys in the original candidate key set.
         std::vector<Index> indices;
         indices.reserve(filteredKeys.size());

         for (const auto& key : filteredKeys)
         {
            indices.push_back(candidate.keySet().getLocalIndex(key));
         }

         // Write the filtered candidate to the buffer at writeIdx.
         buffer.at(writeIdx) = AmbiguityStateWithKeySet{
            candidate.values()(indices),
            candidate.covariance()(indices, indices),
            std::move(filteredKeys)};

         ++writeIdx;
      }
   }

   bufferCount = writeIdx;

   // Clear dropped entries.
   for (std::size_t i = writeIdx; i < originalCount; ++i)
   {
      buffer.at(i) = {};
   }
}

