inline bool
compareBinaryWithExisting(const std::string& fileName, uint8_t const* const data, size_t const size)
{
   const std::string refPath = getBinDir() + fileName;
   std::ifstream refFile(refPath, std::ios::binary | std::ios::ate);
   if (!refFile.is_open())
   {
      std::cout << "- Verifying " << fileName << ": MISSING - See " << fileName << ".tmp\n";

      return false;
   }

   const std::streamsize fileSize = refFile.tellg();
   if (static_cast<size_t>(fileSize) != size)
   {
      std::cout << "- Verifying " << fileName << ": MISMATCH (SIZE) - See " << fileName << ".tmp\n";
      return false;
   }

   refFile.seekg(0, std::ios::beg);

   std::vector<uint8_t> refData(static_cast<size_t>(fileSize));
   readBytes(refFile, refData.data(), static_cast<size_t>(fileSize));
   if (!refFile)
   {
      std::cout << "- Verifying " << fileName << ": ERROR - failed to read\n\n";
      return false;
   }

   const bool match = std::equal(refData.begin(), refData.end(), data);
   if (!match)
   {
      std::cout << "- Verifying " << fileName << ": MISMATCH (CONTENT) - See " << fileName
                << ".tmp\n";
   }
   else
   {
      std::cout << "- Verifying " << fileName << ": OK\n";
   }

   return match;
}

/// @brief Retrieves GPT2 grid data for the specified latitude and longitude indices.
/// @param[out] element The structure to be filled with grid data.
/// @param[in] latIndex Latitude grid index.
/// @param[in] lonIndex Longitude grid index.
/// @return True if the indices are valid and data is retrieved; false otherwise.
bool getGPT2Point(RawGpt2Data& element, const size_t latIndex, const size_t lonIndex)
{
   if (latIndex >= NUMOFLATITUDEGPT2 || lonIndex >= NUMOFLONGITUDEGPT2)
   {
      return false;
   }

   const Gpt2Data tempElement = GPT2_DATA_STRUCT.at(latIndex).at(lonIndex);

   // Convert the parameters as they would be in the original gpt2_5.grd file

   // pressure in Pascal
   element.pa0 = tempElement.pa0;
   element.pa1 = tempElement.pa1;
   element.pb1 = tempElement.pb1;
   element.pa2 = tempElement.pa2;
   element.pb2 = tempElement.pb2;

   // temperature in Kelvin
   element.ta0 = tempElement.ta0 / TEMPERATURE_SCALE;
   element.ta1 = tempElement.ta1 / TEMPERATURE_SCALE;
   element.tb1 = tempElement.tb1 / TEMPERATURE_SCALE;
   element.ta2 = tempElement.ta2 / TEMPERATURE_SCALE;
   element.tb2 = tempElement.tb2 / TEMPERATURE_SCALE;

   // specific humidity in kg/kg
   element.qa0 = tempElement.qa0 / HUMIDITY_SCALE;
   element.qa1 = tempElement.qa1 / HUMIDITY_SCALE;
   element.qb1 = tempElement.qb1 / HUMIDITY_SCALE;
   element.qa2 = tempElement.qa2 / HUMIDITY_SCALE;
   element.qb2 = tempElement.qb2 / HUMIDITY_SCALE;

   // temperature lapse rate in Kelvin/m
   element.dta0 = tempElement.dta0 / TEMPERATURE_LAPSE_RATE_SCALE;
   element.dta1 = tempElement.dta1 / TEMPERATURE_LAPSE_RATE_SCALE;
   element.dtb1 = tempElement.dtb1 / TEMPERATURE_LAPSE_RATE_SCALE;
   element.dta2 = tempElement.dta2 / TEMPERATURE_LAPSE_RATE_SCALE;
   element.dtb2 = tempElement.dtb2 / TEMPERATURE_LAPSE_RATE_SCALE;

   // geoid undulation in m
   element.undu = tempElement.undu / GEOID_UNDULATION_SCALE;

   // hydrostatic mapping function coefficient, dimensionless
   element.ha0 = tempElement.ha0 / HYDROSTATIC_MAPPING_SCALE;
   element.ha1 = tempElement.ha1 / HYDROSTATIC_MAPPING_SCALE;
   element.hb1 = tempElement.hb1 / HYDROSTATIC_MAPPING_SCALE;
   element.ha2 = tempElement.ha2 / HYDROSTATIC_MAPPING_SCALE;
   element.hb2 = tempElement.hb2 / HYDROSTATIC_MAPPING_SCALE;

   // wet mapping function coefficient, dimensionless
   element.wa0 = tempElement.wa0 / WET_MAPPING_SCALE;
   element.wa1 = tempElement.wa1 / WET_MAPPING_SCALE;
   element.wb1 = tempElement.wb1 / WET_MAPPING_SCALE;
   element.wa2 = tempElement.wa2 / WET_MAPPING_SCALE;
   element.wb2 = tempElement.wb2 / WET_MAPPING_SCALE;

   // orthometric grid height in m
   element.hs = static_cast<double>(tempElement.hs) / ORTHOMETRIC_HEIGHT_SCALE;

   return true;
}

bool ConversionManager::processChunk()
{
   // Make sure we have enough data to read the fixed-size header first.
   if (!m_fileManager.fillToMinimum(m_buffer, m_validBytes, GENERIC_HEADER_SIZE))
   {
      if (m_validBytes == ZERO)
      {
         return false;
      }

      if (m_validBytes < GENERIC_HEADER_SIZE)
      {
         PrintHandler::info("Incomplete record at end of file, skipping remaining bytes");
         m_validBytes = ZERO;
         return false;
      }
   }

   BufferReader reader{m_buffer.data(), m_validBytes};

   // Use the official HLF validation method to check record integrity
   uint16_t recordType{0};
   uint32_t payloadLength{0};

   try
   {
      HlfRecord::checkRecord(reader, recordType, payloadLength);
   }
   catch (const std::exception& ex)
   {
      // If we can't validate the record, we've likely hit corrupted data or end of valid data
      PrintHandler::info(
         "Invalid HLF record at position " + std::to_string(m_processedBytes) + ": " + ex.what()
         + ". Ending processing.");
      m_validBytes = ZERO;
      return false;
   }

   // Additional sanity check: payload length should be reasonable (less than 10MB)
   if (static constexpr uint32_t MAX_REASONABLE_PAYLOAD_SIZE = 10U * 1024U * 1024U;
       payloadLength > MAX_REASONABLE_PAYLOAD_SIZE)
   {
      PrintHandler::info(
         "Detected unreasonable payload length (" + std::to_string(payloadLength)
         + " bytes) at position " + std::to_string(m_processedBytes)
         + ", likely corrupted data. Ending processing.");
      m_validBytes = ZERO;
      return false;
   }

   // A complete record consists of the generic header, the payload and the trailing CRC.
   size_t const totalRecordSize
      = GENERIC_HEADER_SIZE + static_cast<size_t>(payloadLength) + CRC_SIZE;

   if (
      !m_fileManager.fillToMinimum(m_buffer, m_validBytes, totalRecordSize)
      && m_validBytes < totalRecordSize)
   {
      if (m_fileManager.eof())
      {
         PrintHandler::info(
            "Incomplete record at end of file (need " + std::to_string(totalRecordSize)
            + " bytes, have " + std::to_string(m_validBytes) + "), skipping remaining bytes");
         m_validBytes = ZERO;
         return false;
      }

      PrintHandler::info(
         "Insufficient data for complete record with payload (need "
         + std::to_string(totalRecordSize) + " bytes, have " + std::to_string(m_validBytes)
         + "), ending processing");
      return false;
   }

   if (recordType == HEADER_RECORD_TYPE)
   {
      m_currentlyProcessingHeaders = true;

      // Extract subtype from header record
      uint8_t subType{ZERO};
      reader.setIndex(GENERIC_HEADER_SIZE);
      reader.read(&subType, sizeof(uint8_t));

      auto record = createHeaderRecord(static_cast<HlfRecordSubType>(subType));
      reader.setIndex(ZERO);
      record->decode(reader);

      m_headerRecords.push(std::move(record));
   }
   else
   {
      m_currentlyProcessingHeaders = false;

      // Create the appropriate record type and decode it
      auto record = std::make_unique<HlfDataRecord>();
      reader.setIndex(ZERO);
      record->decode(reader);

      m_dataRecords.push(std::move(record));
   }

   // We have consumed the entire record (header + payload + CRC).
   compactBuffer(totalRecordSize);

   return true;
}

public:
   /// @brief Deserializes from a provided XML Node to a TimeData<T_DATA> object
   /// Throws an XMLSerializationException if any errors occur
   /// @tparam T_DATA Type of variant of TimeData
   /// @param timeDataNode XML Node to read from
   /// @param timeData TimeData<T_DATA> object to deserialize to
   template <typename T_DATA>
   static void deserialize(mxml_node_t* const timeDataNode, TimeData<T_DATA>& timeData)
   {
      if (timeDataNode != nullptr)
      {
         mxml_node_t* const timeNode = getElementNodeFromPath(timeDataNode, EL_TIME);

         if (timeNode != nullptr)
         {
            TimeXmlDeserializer::deserialize(timeNode, timeData.time);

            deserializeData(timeDataNode, timeData.data);
         }
         else
         {
            throw XmlSerializationException(
               "TimeDataXmlDataDeserializer: Could not find Element: " + std::string(EL_TIME));
         }
      }
      else
      {
         throw XmlSerializationException("TimeDataXmlDataDeserializer: timeDataNode is NULL ");
      }
   }

private:
   /// @brief Deserializes the value of the XML Element, which is a CSV set of values into
   /// the array of doubles provided
   /// @tparam SIZE Size of the Array
   /// @param arrayNode XML node of the Array Element
   /// @param arrayOfDoubles array to deserialize to
   template <unsigned int SIZE>
   static void
   deserializeXmlArray(mxml_node_t* const arrayNode, std::array<double, SIZE>& arrayOfDoubles)
   {
      std::string csvArrayValues;

      if (!getElementStringValue(arrayNode, csvArrayValues))
      {
         throw XmlSerializationException("StochasticVariableXmlDeserializer: deserializeArray: "
                                         "Cannot retrieve CSV String Values");
      }

      const auto noOfItems = getNumberOfItemsInCsv(csvArrayValues);

      if (noOfItems == 0U)
      {
         throw XmlSerializationException(
            "StochasticVariableXmlDeserializer: deserializeArray: No items detected in CSV");
      }

      const auto expectedArraySize = static_cast<unsigned int>(arrayOfDoubles.size());

      if (noOfItems != expectedArraySize)
      {
         throw XmlSerializationException(
            "StochasticVariableXmlDeserializer: deserializeArray: Number of Items in CSV "
            "incorrect");
      }

      try
      {
         arrayOfDoubles.fill(static_cast<double>(0));

         std::stringstream stream(csvArrayValues);
         std::string arrayItem;
         std::size_t idx = 0;
         while (std::getline(stream, arrayItem, ','))
         {
            arrayOfDoubles.at(idx) = std::stod(arrayItem);
            idx++;
         }
      }
      catch (const std::exception&)
      {
         throw XmlSerializationException("StochasticVariableXmlDeserializer: "
                                         "deserializeArray: Cannot convert CSV to "
                                         "an Array");
      }
   }

