std::optional<ClockAndCounter> getClock(
   const GnssKey& sanitizedKey,
   const GnssKeyMap<ClockAndCounter>& cachedClocks,
   const Corrections& corrections,
   const Time& measurementTime,
   const PseudorangeMeasurement& pseudorange)
{
   // If the clock correction is already cached, return it directly.
   const auto clockCorrectionIter = cachedClocks.find(sanitizedKey);
   if (clockCorrectionIter != cachedClocks.end())
   {
      return clockCorrectionIter->second;
   }

   // Otherwise, attempt to find the clock correction polynomial and evaluate it.
   const auto satClockIter = corrections.data.satelliteClock.find(sanitizedKey);
   if (
      satClockIter == corrections.data.satelliteClock.end()
      || !isTimeValid(
         (satClockIter->second.time - measurementTime).value
            + (pseudorange.pseudorange.value / SPEED_OF_LIGHT),
         satClockIter->second.data.timespanHalfValidity))
   {
      return std::nullopt;
   }

   return ClockAndCounter{
      evaluateSatelliteClockCorrection(measurementTime, satClockIter->second, pseudorange),
      satClockIter->second.data.discontinuityCounter};
}

std::uint32_t Crc32::compute(const std::uint8_t* const data, const std::size_t length)
{
   if (data == nullptr)
   {
      throw NullPtrException("Tried to compute crc on nullptr");
   }

   std::uint32_t crc = CRC_INIT;

   for (auto byte : std::basic_string_view<uint8_t>{data, length})
   {
      if constexpr (REFLECT_INPUT)
      {
         byte = static_cast<std::uint8_t>(reflect(byte, EIGHT));
      }

      crc = (crc << EIGHT) ^ LOOKUP_TABLE.at(static_cast<size_t>((crc >> TWENTY_FOUR) ^ byte));
   }

   crc ^= XOROUT;

   if constexpr (REFLECT_OUTPUT)
   {
      crc = reflect(crc, THIRTY_TWO);
   }

   return crc;
}

static void relinearize(
      State<Representation::Information, T_STATE_TYPES...>& state,
      const typename State<Representation::Covariance, T_STATE_TYPES...>::StateVector& delta)
   {
      state.getModifiableLinearizationPoint() = state.getLinearizationPoint() + delta;
      state.getModifiableVector() = state.getVector() - state.getMatrix() * delta;
   }

std::shared_ptr<ApiInvocation> ApiInvocationXmlDeserializer::deserialize(
   mxml_node_t* const apiInvocationNode)
{
   std::shared_ptr<ApiInvocation> apiInvocation = nullptr;

   if (apiInvocationNode != nullptr)
   {
      std::string apiName;
      uint16_t streamId = 0;
      uint64_t timestamp = 0;
      uint32_t threadId = 0;
      std::string errorCodeStr;

      Api api = Api::Invalid;
      ErrorCode errorCode = ErrorCode::Fault;

      validateAndGetAttribute(apiInvocationNode, AT_NAM_API, apiName);
      validateAndGetAttribute(apiInvocationNode, AT_NAM_STREAM_ID, streamId);
      validateAndGetAttribute(apiInvocationNode, AT_NAM_TIMESTAMP, timestamp);
      validateAndGetAttribute(apiInvocationNode, AT_NAM_THREAD_ID, threadId);
      validateAndGetAttribute(apiInvocationNode, AT_NAM_ERROR_CODE, errorCodeStr);

      api = stringToApi(apiName);

      errorCode = stringToErrorCode(errorCodeStr);

      apiInvocation = createInvocation(apiInvocationNode, api, streamId, errorCode);

      // These can't be set via the constructor and should only be updated
      // during XML deserialization
      apiInvocation->setTimestamp(timestamp);
      apiInvocation->setThreadId(threadId);
   }
   else
   {
      throw XmlSerializationException("ApiInvocationXmlDeserializer: apiInvocationNode is NULL ");
   }

   return apiInvocation;
}

