 * (but not including) the specified iterator `targetIt`.
 *
 * @param positionIncrements The deque of position increments.
 * @param targetIt The iterator specifying the end of the range to be removed.
 */
void removePositionIncrementGaps(
   std::deque<Alpha::ReconstructionTraits<Alpha::PositionReconstruction>::IncrementalData>&
      positionIncrements,
   const DequeIncIterator& targetIt)
{
   if (targetIt >= positionIncrements.begin() && targetIt <= positionIncrements.end())
   {
      positionIncrements.erase(positionIncrements.begin(), targetIt);
   }
}

