OrbitPolyT makeOrbitCorrection(const OrbitCorrRecord& src)
{
   OrbitPolyT orbPoly{};
   fillTimeFields(orbPoly.time, src);
   orbPoly.data.discontinuityCounter = src.discontinuityCounter;
   orbPoly.data.timespanHalfValidity = src.halfValidity;

   // coefficients[degree][component]
   for (std::size_t indexI = 0; indexI < 2; ++indexI)
   {
      for (std::size_t indexJ = 0; indexJ < 3; ++indexJ)
      {
         orbPoly.data.coefficients.at(indexI).at(indexJ) = src.polyData.at(indexI).at(indexJ);
      }
   }

   return orbPoly;
}

