ArgumentParser::ArgumentParser(const size_t argc, const char* const* const argv)
{
   if (argc < MIN_ARGUMENT_COUNT || argv == nullptr)
   {
      throw InvalidArgumentException("Argument count or arguments is an invalid value");
   }

   const std::vector<std::string> args = argvToVector(argc, argv, ARGS_OFFSET);
   std::string currentOptionId;
   for (const auto& arg : args)
   {
      // If argument starts with "-", it's a new flag
      if (arg.rfind(FLAG_PREFIX, 0U) == 0U)
      {
         m_activeOptionIds.push_back(arg);
         currentOptionId = arg;           // Set as current option id
         m_options[currentOptionId] = {}; // Initialize empty vector
         continue;
      }
      if (!currentOptionId.empty())
      {
         // If we have a current option id, add the value to its vector
         m_options[currentOptionId].push_back(arg);
         continue;
      }

      throw InvalidArgumentException(
         "An invalid or unsupported command was passed as a first input argument");
   }
}

/// @brief Generates the strategy instance for the synchronizer.
