         TimeRequirement<PositionMeasurement>(TimeMatchingRequirement::OnTimeToPrimary),
         TimeRequirement<VelocityMeasurement>(TimeMatchingRequirement::ClosestToPrimary)};

      // Define package requirements for the strategy.
      const PackageRequirements packageReqs{
         ContentRequirement<GnssMeasurements>(ContentMatchingRequirement::Mandatory),
         ContentRequirement<Corrections>(ContentMatchingRequirement::Mandatory),
         ContentRequirement<PositionMeasurement>(ContentMatchingRequirement::Optional),
         ContentRequirement<VelocityMeasurement>(ContentMatchingRequirement::Optional)};

      return std::make_shared<ThisStrategy>(timeReqs, packageReqs, MINIMUM_DELAY);
   }

