bool sendAndVerify(const std::string& message)
   {
      reset();
      std::vector<uint8_t> data(message.size());
      std::memcpy(data.data(), message.data(), message.size());

      m_mockClient->enqueueData(data);

      if (!waitForData())
      {
         return false;
      }

      auto received = getData();
      if (received.size() != data.size())
      {
         return false;
      }

      for (size_t i = 0; i < data.size(); ++i)
      {
         if (static_cast<uint8_t>(data[i]) != received[i])
         {
            return false;
         }
      }
      return true;
   }

