// Process a received test command
   void process(std::shared_ptr<const TestCommand> command)
   {
      uint32_t result{0U};

      auto action = command->action;

      if (action == TestAction::IncrementCount)
      {
         m_counter++;
      }
      if (action == TestAction::ReadCount)
      {
         result = m_counter;
      }
      else if (action == TestAction::TimeoutOnPrepare)
      {
         m_timeoutOnPrepare = true;
      }
      else if (action == TestAction::TimeoutOnExecute)
      {
         m_timeoutOnExecute = true;
      }
      else if (action == TestAction::DelayOnceWithinTimeout)
      {
         m_delayWithinTimeout = true;
      }

      command->actionCallback(result);
   }

