bool validate(const AmbiguityStateWithKeySet& toValidateCandidate)
{
   if (toValidateCandidate.empty())
   {
      return false;
   }

   static constexpr double SIGNIFICANCE_LEVEL = 0.05;

   // Test if `a' is close enough to its nearest integer vector `z*' in `Z^m' under `Sigma',
   // i.e., Mahalanobis distance: `(a - z*)^T * inv(Sigma) * (a - z*) <= chi^2_m(1 - alpha)'
   using Covariance = AmbiguityStateWithKeySet::Covariance;
   const auto& ambiguitiesVector = toValidateCandidate.values();    // a
   const auto& covarianceMatrix = toValidateCandidate.covariance(); // Sigma

   const auto threshold = computeChiSquareThreshold(
      SIGNIFICANCE_LEVEL,
      static_cast<std::size_t>(ambiguitiesVector.size()));

   // TODO - ALPHA-2578: remove regularizer when ambiguity estimator is robust.
   const LDLT<Covariance> ldlt(
      covarianceMatrix
      + (Covariance::Identity(covarianceMatrix.rows(), covarianceMatrix.cols())
         * std::numeric_limits<double>::epsilon()));

   if (ldlt.info() != ComputationInfo::Success || !ldlt.isPositive())
   {
      return false;
   }

   const auto minDistance = computeSquaredMahalanobisToNearestInteger(ldlt, ambiguitiesVector);
   return minDistance <= threshold;
}

