std::filesystem::path
deriveOutputFilePath(const std::string& inputFilePath, const std::string& outputFolderPath)
{
   namespace fs = std::filesystem;

   if (inputFilePath.empty())
   {
      throw FileException("Input file path is empty when deriving output file path");
   }

   fs::path inputPath{inputFilePath};
   std::string extension = inputPath.extension().string();

   // Normalize the extension to lower-case to ensure case-insensitive comparison.
   static_cast<void>(
      std::transform(extension.begin(), extension.end(), extension.begin(), [](const char chr) {
         return std::tolower(chr, std::locale::classic());
      }));

   // Determine the base output folder (user-provided or default).
   fs::path outputFolder{outputFolderPath.empty() ? DEFAULT_OUTPUT_FOLDER : outputFolderPath};

   fs::path destSubFolder;
   fs::path destPath;

   if (extension == XML_EXTENSION)
   {
      // Converting XML -> HLF.  Place the result under the ".hlf" sub-folder.
      destSubFolder = HLF; // ".hlf"
      destPath = outputFolder / destSubFolder / inputPath.stem();
      destPath.replace_extension(HLF_EXTENSION);
   }
   else if (extension == HLF_EXTENSION)
   {
      // Converting HLF -> XML.  Place the result under the ".xml" sub-folder.
      destSubFolder = XML; // ".xml"
      destPath = outputFolder / destSubFolder / inputPath.stem();
      destPath.replace_extension(XML_EXTENSION);
   }
   else
   {
      throw FileException("Unsupported input file extension: " + extension);
   }

   // Ensure the destination directory exists.
   try
   {
      if (!fs::exists(destPath.parent_path()))
      {
         fs::create_directories(destPath.parent_path());
      }
   }
   catch (const std::exception& ex)
   {
      throw FileException(std::string{"Failed to create output directories: "} + ex.what());
   }

   return destPath;
}

std::shared_ptr<HlfInputDescriptionHeaderRecord>
HlfHeaderRecordXmlDeserializer::deserializeInputDescriptionRecord(
   mxml_node_t* const hlfHeaderRecordNode)
{
   std::shared_ptr<HlfInputDescriptionHeaderRecord> hlfHeaderRecord = nullptr;

   if (hlfHeaderRecordNode != nullptr)
   {
      uint16_t typeId = 0;
      uint16_t originalPort = 0;
      uint16_t dataType = 0;
      std::string originalIp;
      std::string name;
      std::string description;

      if (!getAttributeValue(hlfHeaderRecordNode, AT_HLF_TYPE_ID, typeId))
      {
         throw XmlSerializationException(
            "HlfHeaderRecordXmlDeserializer: Attribute missing or wrong type: "
            + std::string(AT_HLF_TYPE_ID));
      }

      if (!getAttributeValue(hlfHeaderRecordNode, AT_HLF_DATA_TYPE, dataType))
      {
         throw XmlSerializationException(
            "HlfHeaderRecordXmlDeserializer: Attribute missing or wrong type: "
            + std::string(AT_HLF_DATA_TYPE));
      }

      if (!getAttributeValue(hlfHeaderRecordNode, AT_HLF_ORIGINAL_IP, originalIp))
      {
         throw XmlSerializationException(
            "HlfHeaderRecordXmlDeserializer: Attribute missing or wrong type: "
            + std::string(AT_HLF_ORIGINAL_IP));
      }

      if (!getAttributeValue(hlfHeaderRecordNode, AT_HLF_ORIGINAL_PORT, originalPort))
      {
         throw XmlSerializationException(
            "HlfHeaderRecordXmlDeserializer: Attribute missing or wrong type: "
            + std::string(AT_HLF_ORIGINAL_PORT));
      }

      if (!getAttributeValue(hlfHeaderRecordNode, AT_HLF_INPUT_NAME, name))
      {
         throw XmlSerializationException(
            "HlfHeaderRecordXmlDeserializer: Attribute missing or wrong type: "
            + std::string(AT_HLF_INPUT_NAME));
      }

      if (!getAttributeValue(hlfHeaderRecordNode, AT_HLF_INPUT_DESCRIPTION, description))
      {
         throw XmlSerializationException(
            "HlfHeaderRecordXmlDeserializer: Attribute missing or wrong type: "
            + std::string(AT_HLF_INPUT_DESCRIPTION));
      }

      HlfDataType hlfDataType = convertToHlfDataType(dataType);

      // Haven't checked for string sizes as the Hlf<T>HeaderRecord does
      // that and only copies the first 255 chars for string
      hlfHeaderRecord = std::make_shared<HlfInputDescriptionHeaderRecord>(
         typeId,
         hlfDataType,
         originalIp,
         originalPort,
         name,
         description);
   }
   else
   {
      throw XmlSerializationException(
         "HlfHeaderRecordXmlDeserializer: hlfHeaderRecordNode is NULL ");
   }

   return hlfHeaderRecord;
}

void TcpClientReceivingService::serviceThread()
{
   try
   {
      if (m_tcpClient->isConnected())
      {
         m_tcpClient->disconnect();
      }

      m_state = ServiceState::Disconnected;

      while (m_keepRunning.load())
      {
         bool dataReceived = false;

         switch (m_state)
         {
            case ServiceState::Disconnected:
               disconnectedStateHandler();
               break;
            case ServiceState::Reconnecting:
               reconnectingStateHandler();
               break;
            case ServiceState::Connected:
               dataReceived = connectedStateHandler();
               break;
            default:
               break;
         }

         if (m_tcpClient->isConnected() && !dataReceived)
         {
            std::this_thread::sleep_for(std::chrono::milliseconds(YIELD_TIME));
         }
      }

      if (m_tcpClient->isConnected())
      {
         m_tcpClient->disconnect();
      }
   }
   catch (TcpException const& e)
   {
      print(
         PrintLevel::Error,
         "Error on stream " + std::to_string(m_streamId) + ", address "
            + m_tcpClient->getSocketAddress() + ": " + e.what());
      Errors::setErrorState(ErrorCode::TcpError);

      // Signal shutdown so all other client threads are torn down.
      System::shutdown();
   }
   catch (std::exception const& e)
   {
      System::shutdown(
         "Error on stream " + std::to_string(m_streamId) + ", address "
         + m_tcpClient->getSocketAddress() + ": " + e.what());
   }
   catch (...)
   {
      System::shutdown(
         "Unknown exception on stream " + std::to_string(m_streamId) + ", address "
         + m_tcpClient->getSocketAddress());
   }
}

void HlfRecordingDescriptionHeaderRecord::encodePayload(BufferWriter& writer) const
{
   // HLF Recording Description Header payload consists of:
   // - Sub Type:           1 byte
   // - Description Length: 2 bytes
