bool HlfSplitter::updateInputBuffer(
   FileManager& fileManager,
   std::vector<uint8_t>& buffer,
   const std::size_t bytesProcessed,
   std::size_t& bytesToProcess)
{
   bool isEndOfFile = false;

   if (bytesProcessed < bytesToProcess)
   {
      const size_t remaining = bytesToProcess - bytesProcessed;

      shiftBytesToFront(buffer.data(), bytesProcessed, remaining);

      bytesToProcess = remaining;

      static_cast<void>(fileManager.fillBuffer(buffer, bytesToProcess));
   }
   else
   {
      // We have consumed all currently buffered data.
      bytesToProcess = 0U;

      // Try to refill the buffer - if this returns false we are truly at EOF.
      if (!fileManager.fillBuffer(buffer, bytesToProcess))
      {
         isEndOfFile = true;
      }
   }

   return isEndOfFile;
}

