GnssKeyMap<PhaserangeMeasurement> constructPhaserangeMeasurements()
{
   GnssKeyMap<PhaserangeMeasurement> phaseranges; // using default allocator
   for (const auto& signalData : TEST_DATA.data)
   {
      if (signalData.observationType != TestData::ObservationType::Phaserange)
      {
         continue;
      }
      GnssKey key = signalData.key;
      PhaserangeMeasurement phaserange{};
      phaserange.wavelength = signalData.wavelength;
      phaserange.phaseRange.value = constructMeasurement(
         signalData.measurement * signalData.wavelength, // Cycles to meters
         signalData.satelliteClock,
         signalData.externalBias);
      phaserange.phaseRange.covariance
         = signalData.measurementStdDev * signalData.measurementStdDev;
      phaseranges.try_emplace(key, phaserange);
   }

   return GnssKeyMap<PhaserangeMeasurement>(phaseranges);
}

