/**
 * @brief Creates a `Solution` object based on position reconstruction data and optional velocity.
 *
 * This function constructs a `Solution` object using absolute position data, optionally
 * incorporating the latest position increment and velocity data. It sets the position and
 * velocity in the solution's PVT (Position, Velocity, Time) data and combines metadata
 * when applicable.
 *
 * @param reconPos The reconstructed absolute position data, including metadata.
 * @param latestInc The latest incremental position data (optional), including metadata.
 * @param velocity The reconstructed velocity (optional), represented as a stochastic vector.
 * @return A `Solution` object containing the reconstructed position, velocity, and metadata.
 */
Alpha::Solution createSolution(
   const Alpha::ReconstructionTraits<Alpha::PositionReconstruction>::AbsoluteData& reconPos,
   const std::optional<Alpha::ReconstructionTraits<Alpha::PositionReconstruction>::IncrementalData>&
      latestInc,
   const std::optional<Alpha::Velocity>& velocity)
{
   Alpha::Solution solution;
   solution.pvt.time = reconPos.value.time;
   auto pos = reconPos.value.data;
   solution.pvt.data.position = Alpha::Position{};
   solution.pvt.data.position->value = pos.vector3dToArray();
   solution.pvt.data.position->covariance = pos.matrix3dToArray();
   solution.pvt.data.velocity = velocity;

   if (latestInc.has_value())
   {
      const auto& increment = *(latestInc);
      solution.metadata = combine(*(reconPos.metaData), *(increment.metaData));
   }
   else
   {
      solution.metadata = *(reconPos.metaData);
   }

   return solution;
}

// Helper that strictly loads an existing reference binary.  If the file is absent the test will
// fail.
inline std::vector<uint8_t> loadReferenceBinaryStrict(const std::string& filePath)
{
   std::vector<uint8_t> bytes;

   try
   {
      std::cout << "loading file: " << filePath << "\n";

      // Open binary file with exceptions enabled
      std::ifstream file;
      file.exceptions(std::ifstream::failbit | std::ifstream::badbit);
      file.open(filePath, std::ios::binary);

      // Get size of data
      file.seekg(0, std::ios::end);
      size_t size = static_cast<size_t>(file.tellg());
      file.seekg(0, std::ios::beg);

      // Read into vector
      bytes.resize(size);

      readBytes(file, bytes.data(), size);
   }
   catch (const std::ios_base::failure& exc)
   {
      // Capture global errno before it is overwritten
      int errCode = errno;

      // Translate to system error message
      auto errMessage = std::generic_category().message(errCode);
      std::cerr << "Reference file exception: " << errMessage << "\n";

      throw std::runtime_error(
         "Reference file error: " + errMessage + ", stream exception: " + exc.what());
   }

   return bytes;
}

// Format a byte to hex at compile-time constant positions
Alpha::Uuid::UuidString formatUuid(const UuidBinary& binary) noexcept
{
   Alpha::Uuid::UuidString result{};

   // For the UUID structure
   size_t binaryIndex{0U};
   size_t resultIndex{0U};

   // Format each group in sequence
   for (size_t groupNum = 0U; groupNum < GROUP_COUNT; ++groupNum)
   {
      // Format all bytes in the current group
      for (size_t groupByte = 0U; groupByte < BYTES_PER_GROUP.at(groupNum); ++groupByte)
      {
         byteToHex(binary.at(binaryIndex), result.at(resultIndex), result.at(resultIndex + ONE));
         resultIndex += TWO;
         binaryIndex += ONE;
      }

      // Add hyphen after each group except the last one
      if (groupNum < (GROUP_COUNT - ONE))
      {
         result.at(resultIndex) = '-';
         resultIndex += ONE;
      }
   }

   return result;
}

