static void createFile(const std::string& filename, const std::size_t targetFileSize)
{
   std::ofstream logFile(filename, std::ios::binary);

   Alpha::Test::WaitableCounter writeCounter;
   bool sizeReached = false;

   auto logToFile = [&](const void* data, uint32_t size) {
      logFile.write(static_cast<const char*>(data), size);
      if (static_cast<std::size_t>(logFile.tellp()) >= targetFileSize)
      {
         sizeReached = true;
      }
      writeCounter.increment();
   };

   auto apiLogger = ApiLoggerFactory::create(logToFile);
   const uint16_t streamId{1U};

   apiLogger->registerStream(streamId, "TestStream", 1U, LoggingDataType::InputOnly);
   apiLogger->start();

   // Reset — header writes above were synchronous on main thread
   writeCounter.reset();

   // Write some data
   const GnssKey key{Constellation::Galileo, SatelliteId(2), Signal::Rinex9A};
   auto satPos = std::make_shared<Polynomial<ORBIT_POLYNOMIAL_DEGREE, DIMENSION_3D>>();
   Alpha::Test::Data::getPolynomialDataSet1(*satPos);

   auto api = std::make_shared<ProvideSatellitePositionsInvocation>(
      streamId,
      ErrorCode::Success,
      key,
      satPos);

   // Queue one item at a time, waiting for each write to complete before queuing
   // the next. This prevents unbounded queue buildup that would overshoot the
   // target file size.
   uint32_t dataWrites = 0;
   while (!sizeReached)
   {
      apiLogger->log(api);
      ++dataWrites;
      writeCounter.waitFor(dataWrites);
   }

   apiLogger->stop();
   logFile.close();
}

void BufferReader::read(void* const data, size_t const bytes)
{
   if (bytes > getRemainingCapacity())
   {
      throw BufferException("insufficient buffer capacity for read");
   }

   // Source address based on index from start of buffer
   const uint8_t* const src = std::next(m_bufferData, static_cast<ptrdiff_t>(m_index));

   // Destination address
   auto* const dst = static_cast<uint8_t*>(data);

   static_cast<void>(std::copy_n(src, bytes, dst));
   m_index += bytes;
}

