/**
 * @brief Validates that the computed satellite positions match expected values within tolerance.
 *
 * This function checks the X, Y, and Z coordinates of the satellite position for the given GNSS key
 * against the expected values stored in the test case. It uses Catch2's `WithinAbs` matcher with a
 * predefined `EPSILON` tolerance to allow for floating-point comparison.
 *
 * @param testCase   The test case containing expected satellite position values and GNSS key.
 * @param satPositions  Reference to the computed satellite positions map (modified by
 * `applyCorrections`).
 *
 * @pre `satPositions` must contain an entry for `testCase.firstGnssKey`.
 * @pre `testCase.expectedSatPosition` must contain exactly 3 elements: [x, y, z].
 */
void validateSatellitePositions(
   const GnssCorrectorTestCase& testCase,
   const SatellitePositions& satPositions)
{
   static constexpr double SAT_COORD_EPSILON = 1e-4;
   auto checkPosition = [&](const GnssKey& key) {
      REQUIRE_THAT(
         satPositions.at(key).x(),
         Catch::Matchers::WithinAbs(testCase.expectedSatPosition[0], SAT_COORD_EPSILON));
      REQUIRE_THAT(
         satPositions.at(key).y(),
         Catch::Matchers::WithinAbs(testCase.expectedSatPosition[1], SAT_COORD_EPSILON));
      REQUIRE_THAT(
         satPositions.at(key).z(),
         Catch::Matchers::WithinAbs(testCase.expectedSatPosition[2], SAT_COORD_EPSILON));
   };
   checkPosition(testCase.firstGnssKey);
   checkPosition(testCase.secondGnssKey);
}

