uint8_t EntropyCollector::getRandomByte() noexcept
{
   m_counter++;
   m_state = rotateLeft(m_state, PRIMARY_ROTATION_BITS);
   m_state *= MULTIPLIER_PRIME_A;
   m_state ^= m_state >> STATE_DIFFUSION_SHIFT_BITS;
   m_state += m_counter * COUNTER_PRIME;
   m_state = rotateLeft(m_state, SECONDARY_ROTATION_BITS);
   m_state *= MULTIPLIER_PRIME_B;
   m_state ^= static_cast<uint64_t>(
      std::chrono::high_resolution_clock::now().time_since_epoch().count());

   return static_cast<uint8_t>(mix(m_state) & UINT8_MAX_VALUE);
}

