/// @brief Check the publishing intervals for the next package based on the current time.
   ///
   /// @param time The time to check the publishing intervals against.
   void checkPublishingIntervals(const Time& time)
   {
      // Temporary variables.
      Time thresholdTime = time;
      thresholdTime += StochasticScalar{m_minDelay, 0.0};
      // If this is the first package we are publishing, set the minimum and maximum time-stamps
      // and account for the delay
      if (!m_minNextPubTime)
      {
         // Set the minimum time-stamp for the next package.
         m_minNextPubTime = time;
         (*m_minNextPubTime) += StochasticScalar{(-m_createPackageHalfInterval), 0.0};
         // Ensure that we have satisfied the minimum delay for the next package, otherwise incremnt
         // on it until we meet the requirement.
         m_minNextPubTime
            = incrementTimePastThreshold(thresholdTime, (*m_minNextPubTime), m_packageCreatePeriod);
         // Increment past the time of the last created package -- we only need to do it under these
         // conditions (first package after a resynchronization) because it will always be ahead
         // other wise and look in the future.
         m_minNextPubTime = incrementTimePastThreshold(
            std::prev(m_packages.end())->getTime(),
            (*m_minNextPubTime),
            m_packageCreatePeriod);
         // Set the maximum time-stamp for the
         // next package.
         m_maxNextPubTime = (*m_minNextPubTime);
         (*m_maxNextPubTime) += StochasticScalar{(2 * m_createPackageHalfInterval), 0.0};
      }
      else
      {
         // Check if the time-stamp is within the minimum delay from the last published package.
         if (compareLess((*m_minNextPubTime), thresholdTime))
         {
            // If it is, we need to increment the minimum time-stamp for the next package.
            m_minNextPubTime = incrementTimePastThreshold(
               thresholdTime,
               (*m_minNextPubTime),
               m_packageCreatePeriod);

            // Set the maximum time-stamp for the next package.
            m_maxNextPubTime = (*m_minNextPubTime);
            (*m_maxNextPubTime) += StochasticScalar{(2 * m_createPackageHalfInterval), 0.0};
         }
      }
   }

