public:
   /**
    * @brief Computes a hash value for a given GNSS key.
    *
    * The hash is computed by combining the hash of the GNSS constellation type and
    * the satellite ID. A bit shift operation is used to avoid collisions.
    *
    * @param key The GNSS key to hash.
    * @return A hash value for the given GNSS key.
    */
   std::size_t operator()(const GnssKey& key) const
   {
      const std::size_t hash1 = std::hash<int>{}(static_cast<int>(key.constellation));
      const std::size_t hash2 = std::hash<int>{}(key.satelliteId.value);

      static constexpr std::size_t SATELLITE_SHIFT = 1;

      return hash1 ^ (hash2 << SATELLITE_SHIFT);
   }

bool TcpClientReceivingService::handleDataReception()
{
   std::vector<uint8_t> buffer;
   buffer.resize(TCP_BUFFER_SIZE);

   if (!m_tcpClient->receiveData(buffer))
   {
      std::string const tcpError = m_tcpClient->getLastErrorDescription();

      print(
         PrintLevel::Info,
         "Connection error to " + m_tcpClient->getSocketAddress() + " (reason: " + tcpError
            + ") - attempting to reconnect");

      m_tcpClient->disconnect();
      m_state = ServiceState::Reconnecting;
      m_connectionMessagePrinted = false;
      m_dataReceivedMessagePrinted = false;
      return false;
   }

   // Connection was closed
   if (!m_tcpClient->isConnected() && buffer.empty())
   {
      m_keepRunning.store(false);
   }

   if (buffer.empty())
   {
      return false;
   }

   if (m_noDataReceivedReported)
   {
      m_noDataReceivedReported = false;
   }

   m_timeDataLastReceived = std::chrono::steady_clock::now();

   if (!m_dataReceivedMessagePrinted)
   {
      print(PrintLevel::Info, "Data is being received on stream " + std::to_string(m_streamId));

      m_dataReceivedMessagePrinted = true;
   }

   m_callback(m_streamId, buffer);
   return true;
}

void SatellitePolynomialCache::doTimeUpdate(const Time& time, const double windowToKeepSeconds)
{
   if (windowToKeepSeconds < TIME_COMPARISON_EPSILON)
   {
      return;
   }

   // Iterate over all nodes and clear those that are too old
   for (auto& [key, node] : m_data)
   {
      if (node.empty())
      {
         continue;
      }

      const std::shared_ptr<const PositionPolynomial>& latestPolynomial = node.back();
      Time upperBound = latestPolynomial->time;
      upperBound.seconds.value += latestPolynomial->data.timespanHalfValidity;

      const double timeDifference = (time - upperBound).value;
      // Positive and greater than window -> upper bound too far in past
      if (timeDifference > windowToKeepSeconds)
      {
         node.clear();
      }
   }
}

