/**
 * @brief Validates corrected pseudorange and phaserange measurements against expected values.
 *
 * Checks both the value and covariance of:
 * - Pseudorange measurement
 * - Phaserange measurement
 * for the specified GNSS key. Also verifies the phase discontinuity counter.
 *
 * Uses `WithinAbs` matcher with `EPSILON` for floating-point assertions.
 *
 * @param testCase     The test case containing expected corrected measurement values.
 * @param measurements Reference to the GNSS measurements structure after correction.
 *
 * @pre `measurements.data.pseudorangeMeasurements` and `phaserangeMeasurements` must contain
 *      valid entries for `testCase.firstGnssKey`.
 */
void validateCorrectedMeasurements(
   const GnssCorrectorTestCase& testCase,
   const GnssCorrectorOutput& result)
{
   const auto& measurements = result.correctedMeasurements;

   REQUIRE(measurements.data.pseudorangeMeasurements.size() == 2);
   REQUIRE(result.ionoMeasurements.count(testCase.firstSanitizedKey) == 1);

   for (const auto& [key, expectedPr] :
        testCase.expectedGnssMeasurements.data.pseudorangeMeasurements)
   {
      requireEqual(
         measurements.data.pseudorangeMeasurements.at(key).pseudorange,
         expectedPr.pseudorange);
   }

   for (const auto& [key, expectedPh] :
        testCase.expectedGnssMeasurements.data.phaserangeMeasurements)
   {
      requireEqual(
         measurements.data.phaserangeMeasurements.at(key).phaseRange,
         expectedPh.phaseRange);
      REQUIRE(
         measurements.data.phaserangeMeasurements.at(key).discontinuityCounter
         == expectedPh.discontinuityCounter);
   }
}

