/// @brief Get a immutable reference to the covariance of the state.
   /// @return Immutable reference to the covariance of the state.
   ///
   const Covariance& covariance() const
   {
      return m_covariance;
   }

/// @brief Clears the queue in a thread-safe manner
   void clear()
   {
      std::lock_guard<std::mutex> lock(m_mutex);
