   }

/// @brief Get the covariance of the measurement, which is a block diagonal matrix with
      /// uniform
      ///        covariance blocks for each state type, as defined by the individual measurements in
      ///        the container.
      ///
      /// @return Get the covariance of the measurement, which is a block diagonal matrix with
      /// uniform
      ///         covariance blocks for each state type, as defined by the individual measurements
      ///         in the container.
      ///
      Covariance covariance() const
      {
         if (m_stateKeySets == nullptr)
         {
            throw NullPtrException("Dangling pointer to state key sets...");
         }

         // Compute the covariance matrix size based on the state key sets refernced upon
         // construction.
         Index stateDimension = 0;
         std::apply(
            [&](const auto&... keySet) {
               ((stateDimension += static_cast<Index>(keySet.size())
                                 * std::decay_t<decltype(keySet)>::StateType::DIM),
                ...);
            },
            *m_stateKeySets);

         Covariance covariance = Covariance::Zero(stateDimension, stateDimension);

         Index stateStartingIndex = 0;

         std::apply(
            [&](const auto&... keySet) {
               (this->assignStateCovariance(keySet, stateStartingIndex, covariance), ...);
            },
            *m_stateKeySets);

         return covariance;
      }

