private:
   /// @brief Convert an array to a CSV string
   /// @tparam T The type of the array elements
   /// @tparam N The size of the array
   /// @param array The array to convert
   /// @return A string containing the CSV representation of the array
   /// @note This is a static member function that can be used to convert an array to a CSV string.
   template <typename T, std::size_t N>
   static std::string getCSVFromArray(const std::array<T, N>& array)
   {
      if (array.empty())
      {
         return "";
      }

      std::string arrayString = toString<T>(array.at(0));

      for (std::size_t i = 1; i < N; ++i)
      {
         static_cast<void>(arrayString.append(",").append(toString<T>(array.at(i))));
      }

      return arrayString;
   }

