std::string HlfRecordXmlSerializer::encodeDataRecord(const HlfDataRecord& dataRecord)
{
   std::string xml;

   // Serialize the data record
   try
   {
      auto* const xmlNode = HlfXmlSerializer::serializeDataRecord(dataRecord);

      const size_t bufferSize = 1024ULL * 1024ULL;
      static thread_local std::array<char, bufferSize> s_stringBuffer;
      const std::size_t bytesWritten = toString(xmlNode, s_stringBuffer.data(), bufferSize, 1);
      xml = std::string(s_stringBuffer.data(), bytesWritten);

      mxmlDelete(xmlNode);
   }
   catch (const std::exception& ex)
   {
      throw GeneralException(
         "Exception occurred while encoding data record: " + std::string(ex.what()));
   }

   return xml;
}

