void HlfApplicationConfigurationHeaderRecord::decodePayload(BufferReader& reader)
{
   // HLF Application Configuration Header payload consists of:
   // - Sub Type:             1 byte
   // - Configuration Length: 2 bytes
   // - Configuration:        0..65535 bytes

   // Read and verify sub-type is correct for this record type
   uint8_t subType{0U};
   reader.read(&subType, sizeof(uint8_t));

   if (subType == static_cast<uint8_t>(getSubType()))
   {
      // Decode configuration length/data fields
      constexpr size_t arraySize = sizeof(m_configuration);
      HlfHeaderRecord::decodeVarLengthLongString<arraySize>(reader, m_configuration);
   }
}

