std::optional<PseudorangeSignalCorrections>
getPseudorangeSignalCorrections(const GnssKey& gnssKey, const Corrections& corrections)
{
   // Check that all mandatory pseudorange signal-level corrections are available.

   // Pseudorange bias correction is mandatory
   const auto pseudorangeBiasIter = corrections.data.pseudorangeBias.find(gnssKey);
   if (pseudorangeBiasIter == corrections.data.pseudorangeBias.end())
   {
      return std::nullopt;
   }

   // Pseudorange phase center correction is mandatory
   const auto pseudorangePCIter = corrections.data.pseudorangePhaseCenter.find(gnssKey);
   if (pseudorangePCIter == corrections.data.pseudorangePhaseCenter.end())
   {
      return std::nullopt;
   }

   // Having checked that all mandatory corrections are available, populate the output structure.

   PseudorangeSignalCorrections result;
   result.pseudorangeCorrections = std::make_tuple(
      PseudorangeBiasCorrection{
         pseudorangeBiasIter->second.data,
         pseudorangeBiasIter->second.time
   },
      PseudorangePhaseCenter{
         StochasticScalar{pseudorangePCIter->second.data, 0.0},
         pseudorangePCIter->second.time});
   return result;
}

bool operator()(const TPairScalarIndex cPairFirst, const TPairScalarIndex cPairSecond) const
      {
         return (cPairFirst.first < cPairSecond.first);
      }

// print the matrix in a way it can be used for a unit test to reproduce the problem.
//  we cannot just print data with eigen as some rounding makes it not working as a(x,y) != a(y,x)
void printSymmetrixMatrix(const Eigen::MatrixXd& rMatFloatAmbsCov)
{
   for (int i = 0; i < rMatFloatAmbsCov.rows(); i++)
   {
      for (int j = 0; j < rMatFloatAmbsCov.cols(); j++)
      {
         const double candidate = rMatFloatAmbsCov(i, j);
         if (j < i)
         {
            // symmetric, do not print value but print a =
            std::cout << "rMatFloatAmbsCov(" << i << "," << j << ")=" << "rMatFloatAmbsCov(" << j
                      << "," << i << ");" << '\n';
            CHECK(std::abs(candidate - rMatFloatAmbsCov(j, i)) < 0.0000001);
         }
         else
         {
            std::cout << "rMatFloatAmbsCov(" << i << "," << j << ")=" << std::setw(24)
                      << std::scientific << rMatFloatAmbsCov(i, j) << ";" << '\n';
         }
      }
   }
}

void deserialize(BufferReader& reader, TimeData<double>& timeData)
{
   TimeDeserializer::deserialize(reader, timeData.time);
   timeData.data = Deserializer::deserializeFloat64(reader);
}

void Serializer::serializeUint16(BufferWriter& writer, uint16_t const value)
{
   writer.write(&value, sizeof(value));
}

/// @brief Check if lhs is less than rhs within epsilon tolerance
/// @param epsilon Tolerance for comparison (uses default if negative)
inline bool compareLess(const Time& lhs, const Time& rhs, double epsilon = -1.0)
{
   if (epsilon < 0)
   {
      epsilon = TIME_COMPARISON_EPSILON;
   }
   return (lhs - rhs).value < -epsilon;
}
